484	    /// Resolves `refname` (tag, branch, or partial/full SHA) to the commit
485	    /// it points at. An unresolvable ref resolves to `Ok(None)`, which
486	    /// callers treat as "no bound" / "infer over full history".
487	    pub fn resolve_commit(&self, refname: &str) -> Result<Option<CommitSha>, VcsError> {
488	        let rev = format!("{refname}^{{commit}}");
489	        let args = ["rev-parse", "--verify", "--quiet", &rev];
490	        let output = self.runner.run("git", &args, &self.root)?;
491	
492	        if output.exit_code == Some(1) {
493	            return Ok(None);
494	        }
495	        if !output.success() {
496	            return Err(probe_failed(&args, &self.root, &output));
497	        }
498	        let sha_str = output.stdout_trimmed();
499	        if sha_str.is_empty() {
500	            return Ok(None);
501	        }
502	        Ok(CommitSha::parse(sha_str).ok())
503	    }
504	
505	    /// Lists non-merge commits reachable from `HEAD`, down to (exclusive)
506	    /// `since_ref` when given, keeping those that touch at least one of
