1	//! Callisto's single disk-write primitive.
2	//!
3	//! This lives in Layer 1 (`callisto-model`) rather than alongside the manifest
4	//! editors because durable file replacement is not a manifest concern: the
5	//! changelog writer, the pre-mode state file, and the config scaffolder all
6	//! need it too. Hosting it here means those callers do not have to take a
7	//! dependency on `callisto-manifests` purely to reach the filesystem.
8	
9	use std::io::{self, Write};
10	use std::path::Path;
11	
12	use crate::ApplyPermit;
13	use tempfile::NamedTempFile;
14	
15	/// Durably replaces `path`'s contents with `content`.
16	///
17	/// The [`ApplyPermit`] is unused at runtime and exists purely as a compile-time
18	/// obligation: this is callisto's single disk-write primitive, so requiring a
19	/// permit here means no code path can reach the filesystem without having first
20	/// consulted the dry-run flag. See [`crate::permit`].
21	///
22	/// # Errors
23	///
24	/// Returns the first I/O error encountered: creating parent directories, writing the temp file,
25	/// flushing, fsyncing, persisting (renaming) to `path`, or syncing the directory that holds it.
26	pub fn atomic_write(path: &Path, content: &str, permit: &ApplyPermit) -> io::Result<()> {
27	    let _permit = permit;
28	    let raw_parent = path.parent().unwrap_or_else(|| Path::new("."));
29	    let parent = if raw_parent.as_os_str().is_empty() {
30	        Path::new(".")
31	    } else {
32	        raw_parent
33	    };
34	    let created_parent = !parent.try_exists()?;
