1	use std::io::{Read, Write};
2	use std::path::Path;
3	use std::process::Stdio;
4	use std::time::{Duration, Instant};
5	
6	use callisto_model::{known_credential_env_values, redact_known_secrets, CommandError, CommandOutput, CommandRunner};
7	
8	/// Caps how much of a subprocess's stdout/stderr this process will retain
9	/// in memory. The pipe is still drained in full past this point (bytes
10	/// beyond the cap are read and discarded, never accumulated) so a chatty
11	/// child can never deadlock waiting on a full OS pipe buffer -- this
12	/// bounds memory, not duration (`PUBLISH_TIMEOUT_SECS` bounds that
13	/// separately).
14	const MAX_CAPTURED_OUTPUT_BYTES: usize = 10 * 1024 * 1024;
15	
16	const RELEASE_CREDENTIALS: &[&str] = &[
17	    "CARGO_REGISTRY_TOKEN",
18	    "GH_TOKEN",
19	    "GITHUB_TOKEN",
20	    "NPM_CONFIG_TOKEN",
21	    "NPM_TOKEN",
22	    "NODE_AUTH_TOKEN",
23	    "PYPI_TOKEN",
24	    "CALLISTO_PUBLISH_NPM_CONFIG",
25	    "TWINE_USERNAME",
26	    "TWINE_PASSWORD",
27	];
28	
29	const ACTION_SECRET_INPUTS: &[&str] = &[
30	    "CARGO_REGISTRY_TOKEN",
31	    "GH_TOKEN",
32	    "GITHUB_TOKEN",
33	    "NPM_TOKEN",
34	    "PYPI_TOKEN",
35	    "CALLISTO_PUBLISH_NPM_CONFIG",
36	    "TWINE_USERNAME",
37	    "TWINE_PASSWORD",
38	];
39	
40	struct ChildEnvironment<'a> {
41	    remove: &'a [&'a str],
42	    set: &'a [(&'a str, &'a str)],
43	}
44	
45	/// The release credentials a tool reads from its own environment. Every other release
46	/// credential is removed from its child process, so a tool never sees a secret it does not use.
47	/// A tool absent here needs none; publishers receive theirs explicitly instead.
48	fn credentials_needed_by(tool: &str) -> &'static [&'static str] {
49	    match tool {
50	        "npm" | "pnpm" | "yarn" | "bun" => &["NPM_CONFIG_TOKEN", "NPM_TOKEN", "NODE_AUTH_TOKEN"],
51	        "cargo" => &["CARGO_REGISTRY_TOKEN"],
52	        // `gh` reads GH_TOKEN, and GITHUB_TOKEN when that is unset; it runs the attestation
53	        // check and every forge call, and refuses to run without a token.
54	        "gh" => &["GH_TOKEN", "GITHUB_TOKEN"],
55	        _ => &[],
56	    }
57	}
58	
59	fn unrelated_credentials(program: &str) -> Vec<&'static str> {
60	    let tool = Path::new(program)
61	        .file_name()
62	        .and_then(|name| name.to_str())
63	        .unwrap_or(program);
64	    let keep = credentials_needed_by(tool);
65	    RELEASE_CREDENTIALS
66	        .iter()
67	        .copied()
68	        .filter(|credential| !keep.contains(credential))
69	        .collect()
70	}
71	
72	fn remove_env(command: &mut std::process::Command, names: &[&str]) {
73	    for name in names {
74	        command.env_remove(name);
75	    }
76	}
77	
78	pub struct CliCommandRunner;
79	
80	impl CommandRunner for CliCommandRunner {
81	    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
82	        let mut command = std::process::Command::new(program);
83	        command.args(args).current_dir(cwd);
84	        remove_env(&mut command, &unrelated_credentials(program));
85	        let output = command
86	            .stdin(Stdio::null())
87	            .stdout(Stdio::piped())
88	            .stderr(Stdio::piped())
89	            .output();
90	
91	        match output {
92	            Ok(o) => {
93	                let stderr = String::from_utf8_lossy(&o.stderr).into_owned();
94	                // Keep raw stderr available to callers for protocol/error
95	                // classification, but never leak credentials to the terminal.
96	                if !stderr.is_empty() {
97	                    let secrets = known_credential_env_values(std::env::vars());
98	                    eprint!("{}", redact_known_secrets(&stderr, &secrets));
99	                }
100	                Ok(CommandOutput {
101	                    exit_code: o.status.code(),
102	                    stdout: String::from_utf8_lossy(&o.stdout).into_owned(),
103	                    stderr,
104	                })
105	            }
106	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Err(CommandError::NotFound {
107	                program: program.to_string(),
108	            }),
109	            Err(e) => Err(CommandError::Io {
110	                program: program.to_string(),
111	                message: e.to_string(),
112	            }),
113	        }
114	    }
115	
116	    fn run_with_timeout(
117	        &self,
118	        program: &str,
119	        args: &[&str],
120	        cwd: &Path,
121	        timeout: Duration,
122	    ) -> Result<CommandOutput, CommandError> {
123	        // `known_credential_env_values` is scanned here, at the trait-method
124	        // call site, rather than inside `run_with_timeout_impl` itself: this
125	        // keeps the impl fn pure and directly unit-testable with a synthetic
126	        // secrets list (no process-env mutation, which would race against
127	        // other tests running in parallel in this binary).
128	        let remove = unrelated_credentials(program);
129	        run_with_timeout_impl(
130	            program,
131	            args,
132	            cwd,
133	            timeout,
134	            StderrMode::Live,
135	            known_credential_env_values(std::env::vars()),
136	            ChildEnvironment {
137	                remove: &remove,
138	                set: &[],
139	            },
140	        )
141	    }
142	
143	    fn run_with_timeout_env_filtered(
144	        &self,
145	        program: &str,
146	        args: &[&str],
147	        cwd: &Path,
148	        timeout: Duration,
149	        removed: &[&str],
150	    ) -> Result<CommandOutput, CommandError> {
151	        let remove = unrelated_credentials(program)
152	            .into_iter()
153	            .chain(removed.iter().copied())
154	            .collect::<Vec<_>>();
155	        run_with_timeout_impl(
156	            program,
157	            args,
158	            cwd,
159	            timeout,
160	            StderrMode::Live,
161	            known_credential_env_values(std::env::vars()),
162	            ChildEnvironment {
163	                remove: &remove,
164	                set: &[],
165	            },
166	        )
167	    }
168	
169	    fn run_with_timeout_publisher(
170	        &self,
171	        program: &str,
172	        args: &[&str],
173	        cwd: &Path,
174	        timeout: Duration,
175	        env: &[(&str, &str)],
176	    ) -> Result<CommandOutput, CommandError> {
177	        let remove = unrelated_credentials(program)
178	            .into_iter()
179	            .chain(ACTION_SECRET_INPUTS.iter().copied())
180	            .collect::<Vec<_>>();
181	        run_with_timeout_impl(
182	            program,
183	            args,
184	            cwd,
185	            timeout,
186	            StderrMode::Live,
187	            known_credential_env_values(std::env::vars()),
188	            ChildEnvironment {
189	                remove: &remove,
190	                set: env,
191	            },
192	        )
