    root: &Path,
    runner: &dyn CommandRunner,
    expected: &PreparedGitRemote,
) -> Result<(), GraphError> {
    if prepared_git_remote(root, runner)? != *expected {
        return Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::git_remote_changed(),
