219	{
220	    let loaded = load_changesets(&config.root, config)?;
221	    let mut agg = Aggregation::default();
222	
223	    for pkg in graph.packages() {
224	        let cur_sev = agg.severities.get(&pkg.id).copied().unwrap_or(Severity::None);
225	        let pathspecs: Vec<PathBuf> = crate::changed::package_paths(pkg);
226	        let last_tag = tags.last_tag(&pkg.id);
227	        let cur_ver = last_tag
