229	            .or_else(|| base_versions.get(&pkg.id).cloned())
230	            .ok_or_else(|| {
231	                GraphError::Manifest(callisto_model::ManifestError::MissingField {
232	                    path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
